47	    private final byte[] closedState = longSerde.serializer().serialize(null, 0L);
48	    private final AtomicBoolean storeOpen;
49	    // Status marker writes are skipped when true; the check on open still runs.
50	    private final boolean isTransactional;
51	
52	    AbstractColumnFamilyAccessor(final ColumnFamilyHandle offsetColumnFamilyHandle,
53	                                  final AtomicBoolean storeOpen,
54	                                  final boolean isTransactional) {
55	        this.offsetColumnFamilyHandle = offsetColumnFamilyHandle;
56	        this.storeOpen = storeOpen;
57	        this.isTransactional = isTransactional;
58	    }
59	
60	    @Override
61	    public final void commit(final RocksDBStore.DBAccessor accessor,
62	                             final Position position,
63	                             final Map<TopicPartition, Long> changelogOffsets) throws RocksDBException {
64	        if (changelogOffsets.isEmpty()) {
65	            // No changelog: wipe any stale changelog-offset keys left from a prior
66	            // logging configuration, then write the current position below.
67	            wipeOffsets(accessor);
68	        } else {
69	            for (final Map.Entry<TopicPartition, Long> entry : changelogOffsets.entrySet()) {
70	                final TopicPartition tp = entry.getKey();
71	                final Long offset = entry.getValue();
72	                final byte[] key = stringSerializer.serialize(null, tp.toString());
73	                if (offset != null) {
74	                    final byte[] value = longSerde.serializer().serialize(null, offset);
75	                    accessor.put(offsetColumnFamilyHandle, key, value);
76	                } else {
77	                    accessor.delete(offsetColumnFamilyHandle, key);
78	                }
79	            }
80	        }
81	        // Merge committed and uncommitted positions into a temporary copy so that if
82	        // commitStagedWrites() throws, the in-memory position remains consistent with the
83	        // last successful commit. Position is written after wipeOffsets so the key is not
84	        // deleted by the wipe. The in-memory position is updated only on success.
85	        final Position merged = position.copy();
86	        accessor.mergeUncommittedPositionInto(merged);
87	        accessor.put(offsetColumnFamilyHandle, positionKey, PositionSerde.serialize(merged).array());
88	        accessor.commitStagedWrites();
89	        position.merge(merged);
90	    }
91	
92	    @Override
93	    public final Position open(final RocksDBStore.DBAccessor accessor, final boolean ignoreInvalidState) throws RocksDBException {
94	        final byte[] valueBytes = accessor.get(offsetColumnFamilyHandle, statusKey);
95	        if (ignoreInvalidState || (valueBytes == null || Arrays.equals(valueBytes, closedState))) {
96	            if (!isTransactional) {
97	                accessor.put(offsetColumnFamilyHandle, statusKey, openState);
98	            }
99	            storeOpen.set(true);
100	            final byte[] positionBytes = accessor.get(offsetColumnFamilyHandle, positionKey);
101	            if (positionBytes != null) {
102	                return PositionSerde.deserialize(ByteBuffer.wrap(positionBytes));
103	            } else {
104	                return Position.emptyPosition();
105	            }
106	        } else {
107	            throw new ProcessorStateException("Invalid state during store open. Expected state to be either empty or closed");
108	        }
109	    }
110	
111	    @Override
112	    public void close(final RocksDBStore.DBAccessor accessor) throws RocksDBException {
113	        // Only persist the closed state if the store was previously open.
114	        // After an unclean shutdown, RocksDB may still be running background recovery,
115	        // causing accessor.put() to block. The put can also throw if RocksDB is in a
116	        // failed state (e.g. during an EOSv2 fencing cascade); the handle close must
117	        // still happen, otherwise the native ColumnFamilyHandle leaks every cycle.
118	        try {
119	            if (storeOpen.compareAndSet(true, false) && !isTransactional) {
120	                accessor.put(offsetColumnFamilyHandle, statusKey, closedState);
121	            }
122	        } finally {
123	            offsetColumnFamilyHandle.close();
124	        }
125	    }
126	
127	    @Override
128	    public final Long getCommittedOffset(final RocksDBStore.DBAccessor accessor, final TopicPartition partition) throws RocksDBException {
129	        final byte[] valueBytes = accessor.get(offsetColumnFamilyHandle, stringSerializer.serialize(null, partition.toString()));
130	        if (valueBytes != null) {
131	            return longSerde.deserializer().deserialize(null, valueBytes);
132	        }
133	        return null;
134	    }
135	
136	
137	    @Override
138	    public final ColumnFamilyHandle offsetsColumnFamily() {
139	        return offsetColumnFamilyHandle;
140	    }
141	
142	    // Visible for testing
143	    ColumnFamilyHandle offsetColumnFamilyHandle() {
144	        return offsetColumnFamilyHandle;
145	    }
