147	    private void wipeOffsets(final RocksDBStore.DBAccessor accessor) throws RocksDBException {
148	        try (final RocksIterator iter = accessor.newIterator(offsetColumnFamilyHandle)) {
149	            iter.seekToFirst();
150	            while (iter.isValid()) {
151	                final byte[] key = iter.key();
152	                if (!Arrays.equals(key, statusKey)) {
153	                    accessor.delete(offsetColumnFamilyHandle, key);
154	                }
155	                iter.next();
156	            }
157	        }
158	    }
